const MS_PER_DAY = 86_400_000;

function utcDay(value: number): number { return Math.floor(value / MS_PER_DAY); }

/** Whole days since the ISO roast date (e.g. "2026-10-12") as of `today`. */
export function daysSinceRoast(roastedOn: string, today: Date): number {
  const roasted = utcDay(Date.parse(`${roastedOn}T00:00:00Z`));
  const now = utcDay(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate()));
  return now - roasted;
}

/** Fresh for 14 days after roasting, inclusive (day 0 … day 14). */
export function isFresh(roastedOn: string, today: Date): boolean {
  return daysSinceRoast(roastedOn, today) <= 14;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { daysSinceRoast, isFresh } from "../src/freshness.ts";

const today = new Date("2026-10-26T09:30:00Z");

test("day 0: roast day is 0 days old and fresh", () => {
  assert.equal(daysSinceRoast("2026-10-26", today), 0);
  assert.equal(isFresh("2026-10-26", today), true);
});

test("day 14: last fresh day", () => {
  assert.equal(daysSinceRoast("2026-10-12", today), 14);
  assert.equal(isFresh("2026-10-12", today), true);
});

test("day 15: past freshness", () => {
  assert.equal(daysSinceRoast("2026-10-11", today), 15);
  assert.equal(isFresh("2026-10-11", today), false);
});
